mapper.select:
select a.id, a.username, a.password, a.real_name, a.email, a.mobile, a.dept_name, a.status, a.remark, c.english_name englishNames, c.name roleName, c.id roleIds from sys_user a left join sys_user_role b on a.id =b.user_id and b.is_deleted = 0 join sys_role c on b.role_id = c.id and c.is_deleted = 0 and c.id != 3 where a.is_deleted = 0
and a.username like concat ('%',#{dto.username},'%')
and a.status = #{dto.status}
and c.name = #{dto.roleName}
and a.mobile like concat ('%',#{dto.mobile},'%')
and a.email like concat ('%',#{dto.email},'%')
and a.id = #{dto.id}
order by a.update_date desc
